    /**
     * Parse Hoseasons API response
     */
    private parseApiResponse(data: any, params: SearchParams, parkIdFilter?: string): PriceResult[] {
        const results: PriceResult[] = [];

        if (!data.properties || !Array.isArray(data.properties)) {
            console.warn('⚠️  No properties array in API response');
            return [];
        }

        console.log(`📦 Processing ${data.properties.length} properties from API...`);

        data.properties.forEach((property: any) => {
            if (parkIdFilter) {
                // DEBUG: Identify which field matches the parkIdFilter (placesId)

                // Provisional Filtering Logic (commented out until field confirmed)
                // if (String(property.placesId) !== String(parkIdFilter)) return; 
            }

            try {
                // Extract price
                const priceTotalGbp = property.priceFrom || property.lowestPrice;
                if (!priceTotalGbp || typeof priceTotalGbp !== 'number') {
                    return; // Skip if no valid price
                }

                // Extract dates
                const stayStartDate = property.startDate ? new Date(property.startDate).toISOString().split('T')[0] : params.dateWindow.start;

                // Extract nights
                const stayNights = property.lengthOfStay || params.nights.min;

                // Calculate per night price
                const pricePerNightGbp = this.calculatePricePerNight(priceTotalGbp, stayNights);
                if (!pricePerNightGbp) {
                    return;
                }

                // Extract property details
                // Try multiple fields for bedrooms
                let bedrooms = property.bedrooms || property.bedroomCount;

                // If bedrooms missing, try to infer from 'sleeps' or default based on party size
                if (!bedrooms) {
                    if (property.sleeps) {
                        bedrooms = Math.ceil(property.sleeps / 2);
                    } else {
                        // Default to 1 bedroom per 2 adults (safe assumption for parks)
                        bedrooms = Math.ceil((params.party.adults || 1) / 2);
                    }
                }

                // If we searched for pets, assume the result allows pets (API filtering)
                // Otherwise check specific flags
                let petsAllowed: boolean | undefined = params.pets > 0 ? true : undefined;
                if (property.petsGoFree !== undefined) petsAllowed = property.petsGoFree || (params.pets > 0);
                if (property.petFriendly !== undefined) petsAllowed = property.petFriendly;

                // Fallback: If we searched for pets>0, Hoseasons returns pet-friendly places
                if (params.pets > 0 && !petsAllowed) {
                    // Check if 'pets' is in USPs or features
                    const usps = JSON.stringify(property.USPs || []);
                    if (usps.toLowerCase().includes('pet')) {
                        petsAllowed = true;
                    } else {
                        // Trust the search param if we can't find a flag
                        petsAllowed = true;
                    }
                }

                const accomType = property.accommodationType || 'holiday-park';
                const propertyName = property.displayName || property.name || property.title;
                const location = property.location || property.rhs3 || property.regionName;

                // Build source URL
                const sourceUrl = property.code
                    ? `${this.baseUrl}/holiday-parks/${property.code}`
                    : undefined;

                // Classify result
                const candidateRes = {
                    stayStartDate,
                    stayNights,
                    priceTotalGbp,
                    availability: 'AVAILABLE' as const,
                    accomType,
                    bedrooms,
                    petsAllowed
                };

                const matchResult = ResultMatcher.classify(candidateRes, {
                    targetData: {
                        dateStart: params.dateWindow.start,
                        nights: params.nights.min,
                        party: params.party,
                        pets: params.pets,
                        accommodationType: params.accommodation || AccommodationType.ANY,
                        minBedrooms: params.minBedrooms
                    }
                });

                results.push({
                    stayStartDate,
                    stayNights,
                    priceTotalGbp,
                    pricePerNightGbp,
                    availability: 'AVAILABLE',
                    accomType,
                    sourceUrl: this.normalizeUrl(sourceUrl),
                    matchConfidence: matchResult.confidence,
                    matchDetails: matchResult.description,
                    bedrooms,
                    petsAllowed,
                    propertyName,
                    location,
                    parkId: property.code
                });
            } catch (error) {
                console.error('Error parsing property from API:', error);
            }
        });

        console.log(`✅ Parsed ${results.length} valid results from Hoseasons API`);
        return results;
    }

    protected parseSearchResults(_html: string, _params: SearchParams): PriceResult[] {
        // This method is no longer used - we call the API directly now
        console.warn('⚠️  parseSearchResults called but Hoseasons uses API directly');
        return [];
    }

    protected parseOffers(html: string): DealResult[] {
        const $ = cheerio.load(html);
        const deals: DealResult[] = [];

        // Strategy 1: Extract from __NEXT_DATA__ JSON (most reliable - avoids obfuscated class names).
        // The Hoseasons /promotions page is a Next.js app and embeds all CMS data in a script tag.
        const nextDataScript = $('#__NEXT_DATA__').html() ||
            $('script#__NEXT_DATA__').html() ||
            $('script[id="__NEXT_DATA__"]').html();

        if (nextDataScript) {
            try {
                const nextData = JSON.parse(nextDataScript);
                const sections = nextData?.props?.pageProps?.sections || [];

                for (const section of sections) {
                    const items = section?.items || section?.pods || [];
                    for (const item of items) {
                        const title = item?.title || item?.heading;
                        if (!title) continue;

                        const subtitle = item?.subtitle || item?.description || '';
                        const href = item?.link?.href || item?.url || '';

                        // Extract price from subtitle (e.g. "Book today from only £25")
                        const priceMatch = subtitle.match(/£(\d[\d,.]*)/);
                        const discountValue = priceMatch ? parseFloat(priceMatch[1].replace(',', '')) : undefined;

                        const restrictions: Record<string, string> = {};
                        if (subtitle) restrictions['description'] = subtitle;
                        if (href) restrictions['searchUrl'] = href.startsWith('http') ? href : `${this.baseUrl}${href}`;

                        deals.push({
                            title,
                            discountType: discountValue ? 'SALE_PRICE' : 'PERK',
                            discountValue,
                            restrictions
                        });
                    }
                }

                if (deals.length > 0) {
                    return deals;
                }
            } catch (e) {
                console.warn('⚠️  Failed to parse Hoseasons __NEXT_DATA__, falling back to DOM', e);
            }
        }

        // Strategy 2: DOM fallback — find anchor elements linking to Hoseasons search/collections.
        // Uses stable href patterns rather than obfuscated styled-component class names.
        $('a[href*="/search"], a[href*="/collections/"]').each((_, element) => {
            try {
                const $el = $(element);

                const title = $el.find('h2, h3').first().text().trim();
                if (!title) return;

                // Skip nav/footer links - must have some descriptive content
                const allText = $el.text().trim();
                if (allText.length < 10) return;

                const priceMatch = allText.match(/£(\d[\d,.]*)/);
                const discountValue = priceMatch ? parseFloat(priceMatch[1].replace(',', '')) : undefined;

                const href = $el.attr('href') || '';
                const restrictions: Record<string, string> = {};
                if (href) restrictions['searchUrl'] = href.startsWith('http') ? href : `${this.baseUrl}${href}`;

                deals.push({
                    title,
                    discountType: discountValue ? 'SALE_PRICE' : 'PERK',
                    discountValue,
                    restrictions
                });
            } catch (error) {
                console.error('Error parsing Hoseasons offer:', error);
            }
        });

        return deals;
    }
}

import { Worker, Job } from 'bullmq';
import IORedis from 'ioredis';
import { AppDataSource } from '../../config/database';
import { SearchFingerprint } from '../../entities/SearchFingerprint';
import { PriceObservation, AvailabilityStatus } from '../../entities/PriceObservation';
import { ProviderAccomType } from '../../entities/ProviderAccomType';
import { ProviderPark } from '../../entities/ProviderPark';
import { geocodePark } from '../../services/geocoding.service';
import { FetchRun, RunType, RunStatus, ProviderStatus } from '../../entities/FetchRun';
import { adapterRegistry } from '../../adapters/registry';
import { MonitorJobData, addInsightJob } from '../queues';
import { generateSeriesKey } from '../../utils/series-key';
import { SystemLogger } from '../../services/SystemLogger';
import { LocationNotFoundError } from '../../utils/errors';

const fingerprintRepo = AppDataSource.getRepository(SearchFingerprint);
const observationRepo = AppDataSource.getRepository(PriceObservation);
const fetchRunRepo = AppDataSource.getRepository(FetchRun);
const accomTypeRepo = AppDataSource.getRepository(ProviderAccomType);
const parkRepo = AppDataSource.getRepository(ProviderPark);

async function processMonitorJob(job: Job<MonitorJobData>) {
    const { fingerprintId, providerId, searchParams } = job.data;

    console.log(`🔍 Monitoring fingerprint ${fingerprintId} via ${providerId}`);

    // Create fetch run record
    const fetchRun = fetchRunRepo.create({
        provider: { id: providerId } as any,
        fingerprint: { id: fingerprintId } as any,
        runType: RunType.SEARCH,
        scheduledFor: new Date(),
        startedAt: new Date(),
        status: RunStatus.OK,
        providerStatus: ProviderStatus.OK,
    });

    // Save the initial run record
    await fetchRunRepo.save(fetchRun);

    try {
        // Load fingerprint with relations
        const fingerprint = await fingerprintRepo.findOne({
            where: { id: fingerprintId },
            relations: ['provider', 'profile'],
        });

        if (!fingerprint) {
            throw new Error(`Fingerprint ${fingerprintId} not found`);
        }

        // Get adapter
        const adapter = adapterRegistry.getAdapter(fingerprint.provider.code);

        if (!adapter.isEnabled()) {
            console.log(`⚠️  Provider ${fingerprint.provider.code} is disabled, skipping`);
            fetchRun.status = RunStatus.ERROR;
            fetchRun.providerStatus = ProviderStatus.BLOCKED;
            fetchRun.errorMessage = 'Provider disabled';
            await fetchRunRepo.save(fetchRun);
            return;
        }

        // Execute search
        const results = await adapter.search(searchParams);

        // If no results, mark as no results found
        if (results.length === 0) {
            fetchRun.status = RunStatus.NO_RESULTS;
            fetchRun.providerStatus = ProviderStatus.OK;
            fetchRun.errorMessage = 'No availability found for this period';
            fetchRun.finishedAt = new Date();

            const region = searchParams.region || 'Unknown';
            const startDate = searchParams.dateWindow.start;
            const adults = searchParams.party.adults;
            const children = searchParams.party.children || 0;
            const message = `${fingerprint.provider.name}: No results for "${region}" (Start: ${startDate}, Party: ${adults}a/${children}c)`;

            await SystemLogger.warn(
                message,
                'Worker_Monitor',
                { fingerprintId, providerId, params: searchParams }
            );

            await fetchRunRepo.save(fetchRun);
            return;
        }

        console.log(`✅ Found ${results.length} results for fingerprint ${fingerprintId}`);

        // Store observations
        let storedCount = 0;
        for (const result of results) {
            try {
                let accomTypeEntity: ProviderAccomType | null = null;

                if (result.accomType) {
                    // Try to find existing accom type by name and provider
                    accomTypeEntity = await accomTypeRepo.findOne({
                        where: {
                            provider: { id: fingerprint.provider.id },
                            name: result.accomType
                        }
                    });

                    // If not found, create it
                    if (!accomTypeEntity) {
                        try {
                            accomTypeEntity = accomTypeRepo.create({
                                provider: fingerprint.provider,
                                name: result.accomType,
                                providerAccomCode: result.accomType // Use name as code fallback for now
                            });
                            await accomTypeRepo.save(accomTypeEntity);
                        } catch (e) {
                            // Handle race condition where another worker might have created it
                            accomTypeEntity = await accomTypeRepo.findOne({
                                where: {
                                    provider: { id: fingerprint.provider.id },
                                    name: result.accomType
                                }
                            });
                        }
                    }
                }

                // Look up park if parkId provided
                let parkEntity: ProviderPark | null = null;
                if (result.parkId) {
                    // console.log(`🏞️  Looking up park with parkId: ${result.parkId} for provider: ${fingerprint.provider.id}`);
                    parkEntity = await parkRepo.findOne({
                        where: {
                            provider: { id: fingerprint.provider.id },
                            providerParkCode: result.parkId
                        }
                    });

                    // Auto-Create Logic: If park not found but we have details, create it
                    if (!parkEntity && result.propertyName) {
                        console.log(`✨ Park not found, creating new park: ${result.propertyName} (${result.parkId})`);
                        try {
                            parkEntity = parkRepo.create({
                                provider: fingerprint.provider,
                                providerParkCode: result.parkId,
                                name: result.propertyName,
                                region: result.location
                            });
                            await parkRepo.save(parkEntity);
                            console.log(`✅  Created park: ${parkEntity.name}`);
                            // Fire-and-forget geocoding — don't block the monitor job
                            geocodePark(parkEntity).catch(() => {});
                        } catch (e: unknown) {
                            // Handle race condition (unique constraint violation)
                            if ((e as any).message.includes('unique') || (e as any).code === '23505') {
                                console.log(`⚠️ Park already created by another worker, refetching...`);
                                parkEntity = await parkRepo.findOne({
                                    where: {
                                        provider: { id: fingerprint.provider.id },
                                        providerParkCode: result.parkId
                                    }
                                });
                            } else {
                                console.error(`❌ Failed to create park:`, e);
                            }
                        }
                    } else if (parkEntity) {
                        // console.log(`✅ Found existing park: ${parkEntity.name}`);
                    } else {
                        console.log(`⚠️  Park ID ${result.parkId} found but no name provided in result, cannot create.`);
                    }
                } else {
                    // console.log(`⚠️  No parkId in result for series`);
                }

                // Generate series key
                const seriesKey = generateSeriesKey({
                    providerId: fingerprint.provider.id,
                    stayStartDate: result.stayStartDate,
                    stayNights: result.stayNights,
                    parkId: result.parkId,
                    accomTypeId: accomTypeEntity?.id || result.accomType, // Prefer ID if available
                });

                // Create observation
                const observation = observationRepo.create({
                    provider: fingerprint.provider,
                    fingerprint,
                    fetchRun,
                    stayStartDate: new Date(result.stayStartDate),
                    stayNights: result.stayNights,
                    seriesKey,
                    partySize: {
                        adults: searchParams.party.adults,
                        children: searchParams.party.children,
                    },
                    priceTotalGbp: result.priceTotalGbp,
                    pricePerNightGbp: result.pricePerNightGbp || result.priceTotalGbp / result.stayNights,
                    availability: (result.availability as AvailabilityStatus) || AvailabilityStatus.AVAILABLE,
                    sourceUrl: result.sourceUrl,
                    accomType: accomTypeEntity || undefined,
                    park: parkEntity || undefined,
                });

                await observationRepo.insert(observation as any);
                storedCount++;
            } catch (err) {
                console.error(`Failed to store observation:`, err);
                // Continue with other results
            }
        }

        console.log(`💾 Stored ${storedCount}/${results.length} observations`);

        // Update fetch run for success
        fetchRun.finishedAt = new Date();
        fetchRun.status = RunStatus.OK;
        fetchRun.providerStatus = ProviderStatus.OK;
        await fetchRunRepo.save(fetchRun);

        // Queue insight generation
        await addInsightJob({ fingerprintId });

        // Update fingerprint last scheduled time
        fingerprint.lastScheduledAt = new Date();
        await fingerprintRepo.save(fingerprint);

    } catch (error: unknown) {
        const errorMessage = error instanceof Error ? error.message : 'Unknown error';
        console.error(`❌ Monitor job failed for fingerprint ${job.data.fingerprintId}:`, error);

        // Log critical failure to System Logs
        await SystemLogger.error(
            `Monitor Job Failed: ${errorMessage}`,
            'Worker_Monitor',
            { fingerprintId, providerId, stack: error instanceof Error ? error.stack : undefined }
        );

        // Update fetch run with error
        fetchRun.status = error instanceof LocationNotFoundError ? RunStatus.INVALID_LOCATION : RunStatus.ERROR;
        fetchRun.errorMessage = errorMessage;
        fetchRun.finishedAt = new Date();

        if (errorMessage.includes('timeout')) {
            fetchRun.providerStatus = ProviderStatus.TIMEOUT;
        } else if (errorMessage.includes('blocked') || errorMessage.includes('403')) {
            fetchRun.providerStatus = ProviderStatus.BLOCKED;
        } else if (errorMessage.includes('parse') || errorMessage.includes('JSON')) {
            fetchRun.providerStatus = ProviderStatus.PARSE_FAILED;
        } else {
            fetchRun.providerStatus = ProviderStatus.FETCH_FAILED;
        }

        await fetchRunRepo.save(fetchRun);
        throw error; // Let BullMQ handle retry
    }
}

export const monitorWorker = new Worker('monitor', processMonitorJob, {
    connection: new IORedis({
        host: process.env.REDIS_HOST || 'localhost',
        port: parseInt(process.env.REDIS_PORT || '6379'),
        password: process.env.REDIS_PASSWORD || undefined,
        maxRetriesPerRequest: null,
        enableReadyCheck: false
    }),
    concurrency: parseInt(process.env.PROVIDER_MAX_CONCURRENT || '2'),
});

monitorWorker.on('error', (err) => {
    console.error('❌ Monitor Worker Connection Error:', err);
});

monitorWorker.on('completed', (job) => {
    console.log(`✅ Monitor job ${job.id} completed`);
});

monitorWorker.on('failed', async (job, err) => {
    // Double log here in case it failed outside the process function
    if (job) {
        await SystemLogger.error(
            `BullMQ Job Failed: ${err.message}`,
            'Worker_Monitor_Queue',
            { jobId: job.id, name: job.name }
        );
    }
    console.error(`❌ Monitor job ${job?.id} failed:`, err);
});

import { FastifyRequest, FastifyReply } from 'fastify';
import { AppDataSource } from '../config/database';
import { User, UserRole } from '../entities/User';
import { JWTPayload } from '../types/common.types';

declare module 'fastify' {
    interface FastifyInstance {
        authenticate: (request: FastifyRequest, reply: FastifyReply) => Promise<void>;
        requireAdmin: (request: FastifyRequest, reply: FastifyReply) => Promise<void>;
    }
}

export async function authenticate(request: FastifyRequest, reply: FastifyReply) {
    try {
        await request.jwtVerify();
    } catch (err) {
        reply.status(401).send({ error: 'Unauthorized' });
    }
}

export async function requireAdmin(request: FastifyRequest, reply: FastifyReply) {
    try {
        await request.jwtVerify();
        const userId = (request.user as JWTPayload).userId;

        const userRepo = AppDataSource.getRepository(User);
        const user = await userRepo.findOne({ where: { id: userId } });

        if (!user || user.role !== UserRole.ADMIN) {
            reply.status(403).send({ error: 'Forbidden: Admin access required' });
        }
    } catch (err) {
        reply.status(401).send({ error: 'Unauthorized' });
    }
}

export function getUserId(request: FastifyRequest): string {
    const payload = request.user as JWTPayload;
    return payload.userId;
}

import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { authService } from '../services/auth.service';
import { emailService } from '../services/email.service';
import { authenticate } from '../middleware/auth';

const registerSchema = z.object({
    email: z.string().email(),
    password: z.string().min(8),
});

const loginSchema = z.object({
    email: z.string().email(),
    password: z.string(),
});

const verifyEmailSchema = z.object({
    token: z.string(),
});

const resetPasswordRequestSchema = z.object({
    email: z.string().email(),
});

const resetPasswordSchema = z.object({
    token: z.string(),
    password: z.string().min(8),
});

export async function authRoutes(fastify: FastifyInstance) {
    // Register
    fastify.post('/auth/register', async (request, reply) => {
        try {
            const { email, password } = registerSchema.parse(request.body);

            const user = await authService.createUser(email, password);

            // Send verification email
            if (user.verificationToken) {
                await emailService.sendVerificationEmail(email, user.verificationToken);
            }

            reply.status(201).send({
                message: 'User created successfully. Please check your email to verify your account.',
                userId: user.id,
            });
        } catch (error: any) {
            if (error.message === 'User already exists') {
                reply.status(409).send({ error: error.message });
            } else {
                reply.status(400).send({ error: error.message });
            }
        }
    });

    // Login
    fastify.post('/auth/login', async (request, reply) => {
        try {
            const { email, password } = loginSchema.parse(request.body);

            const user = await authService.findByEmail(email);
            if (!user) {
                reply.status(401).send({ error: 'Invalid credentials' });
                return;
            }

            const isValid = await authService.comparePassword(password, user.passwordHash);
            if (!isValid) {
                reply.status(401).send({ error: 'Invalid credentials' });
                return;
            }

            if (!user.emailVerified) {
                reply.status(403).send({ error: 'Please verify your email before logging in' });
                return;
            }

            const token = fastify.jwt.sign({ userId: user.id });

            reply.send({
                token,
                user: {
                    id: user.id,
                    email: user.email,
                    emailVerified: user.emailVerified,
                },
            });
        } catch (error: any) {
            reply.status(400).send({ error: error.message });
        }
    });

    // Verify Email
    fastify.post('/auth/verify-email', async (request, reply) => {
        try {
            const { token } = verifyEmailSchema.parse(request.body);

            const user = await authService.verifyEmail(token);

            reply.send({
                message: 'Email verified successfully',
                user: {
                    id: user.id,
                    email: user.email,
                    emailVerified: user.emailVerified,
                },
            });
        } catch (error: any) {
            reply.status(400).send({ error: error.message });
        }
    });

    // Request Password Reset
    fastify.post('/auth/reset-password-request', async (request, reply) => {
        try {
            const { email } = resetPasswordRequestSchema.parse(request.body);

            const token = await authService.initiatePasswordReset(email);
            await emailService.sendPasswordResetEmail(email, token);

            reply.send({
                message: 'Password reset email sent. Please check your inbox.',
            });
        } catch (error: any) {
            // Don't reveal if user exists
            reply.send({
                message: 'If an account exists with that email, a password reset link has been sent.',
            });
        }
    });

    // Reset Password
    fastify.post('/auth/reset-password', async (request, reply) => {
        try {
            const { token, password } = resetPasswordSchema.parse(request.body);

            await authService.resetPassword(token, password);

            reply.send({
                message: 'Password reset successfully. You can now log in with your new password.',
            });
        } catch (error: any) {
            reply.status(400).send({ error: error.message });
        }
    });

    // Get current user (protected route)
    fastify.get('/auth/me', {
        preHandler: [authenticate],
    }, async (request, reply) => {
        const userId = (request.user as { userId: string }).userId;
        const user = await authService.findById(userId);

        if (!user) {
            reply.status(404).send({ error: 'User not found' });
            return;
        }

        reply.send({
            id: user.id,
            email: user.email,
            emailVerified: user.emailVerified,
            notificationsEnabled: user.notificationsEnabled,
            notificationChannels: user.notificationChannels,
            digestMode: user.digestMode,
        });
    });


    // Change Password (protected)
    fastify.post('/auth/change-password', {
        preHandler: [authenticate],
    }, async (request, reply) => {
        try {
            const schema = z.object({
                currentPassword: z.string(),
                newPassword: z.string().min(8)
            });
            const { currentPassword, newPassword } = schema.parse(request.body);
            const userId = (request.user as any).userId;

            await authService.changePassword(userId, currentPassword, newPassword);

            reply.send({ message: 'Password updated successfully' });
        } catch (error: any) {
            reply.status(400).send({ error: error.message });
        }
    });
}

import { AppDataSource } from '../config/database';
import { PriceObservation } from '../entities/PriceObservation';
import { Insight, InsightType } from '../entities/Insight';
import { Deal, DealSource, DiscountType } from '../entities/Deal';
import { SearchFingerprint } from '../entities/SearchFingerprint';
import { generateInsightDedupeKey } from '../utils/series-key';

const observationRepo = AppDataSource.getRepository(PriceObservation);
const insightRepo = AppDataSource.getRepository(Insight);
const dealRepo = AppDataSource.getRepository(Deal);
const fingerprintRepo = AppDataSource.getRepository(SearchFingerprint);

export class InsightService {
    /**
     * Generate insights for a specific fingerprint
     * Uses series-based analysis to ensure like-for-like comparisons
     */
    async generateInsights(fingerprintId: string): Promise<Insight[]> {
        const insights: Insight[] = [];

        // Step 1: Get all distinct series keys for this fingerprint
        const seriesKeysResult = await observationRepo
            .createQueryBuilder('obs')
            .select('DISTINCT obs.seriesKey', 'seriesKey')
            .where('obs.fingerprint_id = :fingerprintId', { fingerprintId })
            .getRawMany();

        console.log(`Found ${seriesKeysResult.length} distinct series for fingerprint ${fingerprintId}`);

        // Step 2: For each series, run insight analysis
        for (const { seriesKey } of seriesKeysResult) {
            const seriesInsights = await this.analyzeSeriesInsights(fingerprintId, seriesKey);
            insights.push(...seriesInsights);
        }

        return insights;
    }

    /**
     * Analyze a single series for insights
     */
    private async analyzeSeriesInsights(fingerprintId: string, seriesKey: string): Promise<Insight[]> {
        const insights: Insight[] = [];

        // Get observations for this series, ordered by time
        const observations = await observationRepo.find({
            where: {
                fingerprint: { id: fingerprintId },
                seriesKey,
            },
            order: { observedAt: 'DESC' },
        });

        if (observations.length === 0) {
            return insights;
        }

        // Check for lowest price in X days
        const lowestInsight = await this.checkLowestInXDays(fingerprintId, seriesKey, observations);
        if (lowestInsight) {
            insights.push(lowestInsight);
            await this.createDealFromInsight(fingerprintId, seriesKey, lowestInsight);
        }

        // Check for price drop
        const dropInsight = await this.checkPriceDrop(fingerprintId, seriesKey, observations);
        if (dropInsight) {
            insights.push(dropInsight);
            await this.createDealFromInsight(fingerprintId, seriesKey, dropInsight);
        }

        // Check for rising risk
        const riskInsight = await this.checkRisingRisk(fingerprintId, seriesKey, observations);
        if (riskInsight) insights.push(riskInsight);

        // Save all insights (with deduplication)
        for (const insight of insights) {
            try {
                await insightRepo.save(insight);
            } catch (error) {
                // Unique constraint violation - insight already exists
                console.log(`Insight already exists for dedupe key: ${insight.dedupeKey}`);
            }
        }

        return insights;
    }

    /**
     * Create or update a Deal entity based on an Insight
     */
    private async createDealFromInsight(
        fingerprintId: string,
        seriesKey: string,
        insight: Insight
    ): Promise<void> {
        try {
            // Get fingerprint to identify provider
            const fingerprint = await fingerprintRepo.findOne({
                where: { id: fingerprintId },
                relations: ['provider'],
            });

            if (!fingerprint || !fingerprint.provider) {
                console.warn(`Could not find provider for fingerprint ${fingerprintId}, skipping deal creation`);
                return;
            }

            const sourceRef = seriesKey; // Use seriesKey as unique reference for this specific holiday option
            const existingDeal = await dealRepo.findOne({
                where: {
                    source: DealSource.PROVIDER_OFFERS,
                    sourceRef,
                },
            });

            let discountType = DiscountType.FIXED_OFF;
            let discountValue = 0;

            if (insight.type === InsightType.PRICE_DROP_PERCENT) {
                discountType = DiscountType.PERCENT_OFF;
                discountValue = (insight.details as any).percentDrop || 0;
            } else if (insight.type === InsightType.LOWEST_IN_X_DAYS) {
                // For lowest price, we can treat the difference from previous min as a 'deal'
                // Use a heuristic or default
                discountType = DiscountType.SALE_PRICE;
                discountValue = Number(insight.details.currentPrice);
            }

            if (existingDeal) {
                // Update existing deal
                existingDeal.lastSeenAt = new Date();
                existingDeal.confidence = Math.min(existingDeal.confidence + 0.1, 1.0);
                if (insight.details.currentPrice) {
                    existingDeal.discountValue = discountValue; // Update value
                }
                await dealRepo.save(existingDeal);
                console.log(`Updated deal for series ${seriesKey}`);
            } else {
                // Create new deal
                const newDeal = dealRepo.create({
                    provider: fingerprint.provider,
                    source: DealSource.PROVIDER_OFFERS,
                    sourceRef,
                    title: insight.summary,
                    discountType,
                    discountValue,
                    startsAt: new Date(),
                    lastSeenAt: new Date(),
                    detectedAt: new Date(),
                    confidence: 0.7,
                    eligibilityTags: ['price_drop'],
                    restrictions: {
                        stayStartDate: insight.details.stayStartDate,
                        stayNights: insight.details.stayNights,
                    },
                });
                await dealRepo.save(newDeal);
                console.log(`Created new deal for series ${seriesKey}`);
            }
        } catch (error) {
            console.error('Failed to create/update deal from insight:', error);
        }
    }

    /**
     * Check if current price is lowest in X days (within same series)
     */
    private async checkLowestInXDays(
        fingerprintId: string,
        seriesKey: string,
        observations: PriceObservation[]
    ): Promise<Insight | null> {
        const windowDays = 180;
        const minObservations = 5;

        // Require minimum observations for confidence
        if (observations.length < minObservations) {
            return null;
        }

        const cutoffDate = new Date();
        cutoffDate.setDate(cutoffDate.getDate() - windowDays);

        // Query observations within window for this series
        const windowObservations = await observationRepo.find({
            where: {
                fingerprint: { id: fingerprintId },
                seriesKey,
            },
            order: { observedAt: 'DESC' },
        });

        const recentObs = windowObservations.filter(obs => obs.observedAt >= cutoffDate);

        if (recentObs.length < minObservations) {
            return null;
        }

        const latest = observations[0];
        const minPrice = Math.min(...recentObs.map(obs => Number(obs.priceTotalGbp)));

        if (Number(latest.priceTotalGbp) <= minPrice) {
            const dedupeKey = generateInsightDedupeKey({
                fingerprintId,
                seriesKey,
                insightType: InsightType.LOWEST_IN_X_DAYS,
                windowIdentifier: 'LOWEST_180D',
            });

            return insightRepo.create({
                fingerprint: { id: fingerprintId },
                type: InsightType.LOWEST_IN_X_DAYS,
                seriesKey,
                dedupeKey,
                summary: `Lowest price in ${windowDays} days: £${latest.priceTotalGbp}`,
                details: {
                    currentPrice: latest.priceTotalGbp,
                    previousMin: minPrice,
                    windowDays,
                    observationCount: recentObs.length,
                    stayStartDate: latest.stayStartDate,
                    stayNights: latest.stayNights,
                    seriesKey,
                },
            });
        }

        return null;
    }

    /**
     * Check for meaningful price drop (within same series)
     */
    private async checkPriceDrop(
        fingerprintId: string,
        seriesKey: string,
        observations: PriceObservation[]
    ): Promise<Insight | null> {
        if (observations.length < 2) {
            return null;
        }

        const latest = observations[0];
        const previous = observations[1];

        const priceDiff = Number(previous.priceTotalGbp) - Number(latest.priceTotalGbp);
        const percentDrop = (priceDiff / Number(previous.priceTotalGbp)) * 100;

        // Threshold: drop >= max(£75, 7%)
        const minAbsoluteDrop = 75;
        const minPercentDrop = 7;

        if (priceDiff >= minAbsoluteDrop || percentDrop >= minPercentDrop) {
            const dedupeKey = generateInsightDedupeKey({
                fingerprintId,
                seriesKey,
                insightType: InsightType.PRICE_DROP_PERCENT,
                windowIdentifier: 'PRICE_DROP',
            });

            return insightRepo.create({
                fingerprint: { id: fingerprintId },
                type: InsightType.PRICE_DROP_PERCENT,
                seriesKey,
                dedupeKey,
                summary: `Price dropped by £${priceDiff.toFixed(2)} (${percentDrop.toFixed(1)}%)`,
                details: {
                    currentPrice: latest.priceTotalGbp,
                    previousPrice: previous.priceTotalGbp,
                    absoluteDrop: priceDiff,
                    percentDrop,
                    stayStartDate: latest.stayStartDate,
                    stayNights: latest.stayNights,
                    seriesKey,
                },
            });
        }

        return null;
    }

    /**
     * Check for rising booking risk (within same series)
     */
    private async checkRisingRisk(
        fingerprintId: string,
        seriesKey: string,
        observations: PriceObservation[]
    ): Promise<Insight | null> {
        const minObservations = 5;

        if (observations.length < minObservations) {
            return null;
        }

        const recent = observations.slice(0, minObservations);
        const soldOutCount = recent.filter(obs => obs.availability === 'SOLD_OUT').length;

        // Check if prices are trending up within this series
        const prices = recent.map(obs => Number(obs.priceTotalGbp));
        const avgRecentPrice = prices.slice(0, 2).reduce((a, b) => a + b, 0) / 2;
        const avgOlderPrice = prices.slice(3, 5).reduce((a, b) => a + b, 0) / 2;

        const priceIncrease = avgRecentPrice > avgOlderPrice;

        if (soldOutCount >= 2 && priceIncrease) {
            const dedupeKey = generateInsightDedupeKey({
                fingerprintId,
                seriesKey,
                insightType: InsightType.RISK_RISING,
                windowIdentifier: 'RISK_RISING',
            });

            return insightRepo.create({
                fingerprint: { id: fingerprintId },
                type: InsightType.RISK_RISING,
                seriesKey,
                dedupeKey,
                summary: `Booking risk rising: ${soldOutCount} sold out dates, prices increasing`,
                details: {
                    soldOutCount,
                    totalChecked: recent.length,
                    avgRecentPrice,
                    avgOlderPrice,
                    priceIncrease: avgRecentPrice - avgOlderPrice,
                    seriesKey,
                },
            });
        }

        return null;
    }

    /**
     * Get all insights for a fingerprint
     */
    async getInsights(fingerprintId: string, limit: number = 20): Promise<Insight[]> {
        return insightRepo.find({
            where: { fingerprint: { id: fingerprintId } },
            order: { createdAt: 'DESC' },
            take: limit,
        });
    }
}

export const insightService = new InsightService();

import { AppDataSource } from '../../config/database';
import { HolidayProfile, PeakTolerance } from '../../entities/HolidayProfile';
import { FetchRun, RunType, RunStatus, ProviderStatus } from '../../entities/FetchRun';
import { Provider } from '../../entities/Provider';
import { adapterRegistry } from '../../adapters/registry';
import { ResultMatcher, MatchConfidence } from '../../utils/result-matcher';
import { v4 as uuidv4 } from 'uuid';
import { generateSeriesKey } from '../../utils/series-key';
import { SearchParams, PriceResult } from '../../adapters/base.adapter';
import { TripCostService } from '../trip-cost.service';
import { User } from '../../entities/User';

// Types from spec
export type PreviewMode = 'PROFILE_ID' | 'INLINE_PROFILE';

export interface PreviewRequest {
    mode: PreviewMode;
    profileId?: string;
    profile?: Partial<HolidayProfile>; // Inline profile
    providers?: string[];
    options?: PreviewOptions;
    userId: string; // Required for security
}

export interface PreviewOptions {
    maxResults?: number;
    enrichTopN?: number;
    allowWeakMatches?: boolean;
    includeMismatches?: boolean;
    includeDebug?: boolean;
    forcePlaywright?: boolean;
    includeRaw?: boolean;
}

export interface ProviderPreview {
    providerKey: string;
    status: string;
    timingMs: {
        fetch: number;
        parse: number;
        match: number;
        enrich: number;
        total: number;
    };
    compliance: {
        scrapingEnabled: boolean;
        robotsAllowed: boolean;
        playwrightUsed: boolean;
        rateLimited: boolean;
    };
    results: {
        matched: PreviewResult[];
        other: PreviewResult[];
    };
    summary: {
        totalCandidates: number;
        matchStrong: number;
        matchWeak: number;
        matchUnknown: number;
        mismatch: number;
        lowestMatchedPriceGbp: number | null;
    };
}

export interface PreviewResult {
    confidence: MatchConfidence;
    providerKey: string;
    sourceUrl: string;
    parkId: string;
    stayStartDate: string; // yyyy-mm-dd
    stayNights: number;
    accommodationType?: string;
    bedrooms?: number;
    tier?: string;
    petsAllowed?: boolean;
    facilities?: string[];
    propertyName?: string;
    location?: string;
    availability: 'AVAILABLE' | 'SOLD_OUT' | 'UNKNOWN';
    price: {
        totalGbp: number;
        perNightGbp: number | null;
    };
    tripCost?: {
        distanceMiles: number;
        drivingMinutes: number;
        fuelCostGbp: number;
        ferryCostGbp: number;
        onParkEstLow: number;
        onParkEstHigh: number;
        totalLow: number;
        totalHigh: number;
        isEstimate: boolean;
    };
    seriesKey: string;
    reasons: {
        passed: Reason[];
        failed: Reason[];
        unknown: Reason[];
        softNotes: Reason[];
    };
    matchDetails?: string;
}

export interface Reason {
    code: string;
    message: string;
    details?: Record<string, unknown>;
}

export interface PreviewResponse {
    requestId: string;
    generatedAt: string;
    mode: PreviewMode;
    profile: Record<string, unknown>;
    providers: ProviderPreview[];
    overallSummary: Record<string, unknown>;
    sideEffects: {
        observationsStored: boolean;
        alertsGenerated: boolean;
        emailsSent: boolean;
    };
    warnings: unknown[];
}

export class PreviewService {
    private fetchRunRepo = AppDataSource.getRepository(FetchRun);
    private providerRepo = AppDataSource.getRepository(Provider);
    private profileRepo = AppDataSource.getRepository(HolidayProfile);
    private userRepo = AppDataSource.getRepository(User);
    private tripCostService = TripCostService.getInstance();

    async executePreview(req: PreviewRequest): Promise<PreviewResponse> {
        const requestId = uuidv4();
        const generatedAt = new Date().toISOString();
        const providerPreviews: ProviderPreview[] = [];

        // 1. Resolve Profile with User Scoping
        let profile: HolidayProfile | Partial<HolidayProfile>;
        if (req.mode === 'PROFILE_ID') {
            if (!req.profileId) throw new Error('profileId required for PROFILE_ID mode');

            // SECURITY: Enforce user scoping
            const found = await this.profileRepo.findOne({
                where: {
                    id: req.profileId,
                    user: { id: req.userId }
                },
                relations: ['provider'] // Load provider relation
            });

            if (!found) {
                throw new Error('Profile not found or access denied');
            }
            profile = found;
        } else {
            if (!req.profile) throw new Error('profile payload required for INLINE_PROFILE mode');

            // VALIDATION: Enforce minimum viable profile
            if (!req.profile.dateStart) {
                throw new Error('PROFILE_INCOMPLETE: dateStart is required');
            }

            // For RANGE/FLEXI, dateEnd is required
            if (req.profile.flexType === 'RANGE' || req.profile.flexType === 'FLEXI') {
                if (!req.profile.dateEnd) {
                    throw new Error('PROFILE_INCOMPLETE: dateEnd is required for RANGE/FLEXI mode');
                }
            }

            // Validate dates are not Invalid Date objects
            const startDate = new Date(req.profile.dateStart);
            if (isNaN(startDate.getTime())) {
                throw new Error('PROFILE_INCOMPLETE: dateStart is invalid');
            }

            if (req.profile.dateEnd) {
                const endDate = new Date(req.profile.dateEnd);
                if (isNaN(endDate.getTime())) {
                    throw new Error('PROFILE_INCOMPLETE: dateEnd is invalid');
                }
            }

            profile = req.profile;
        }

        // 2. Determine Providers with Normalization
        // Get all available providers and normalize to uppercase
        const allProviders = Array.from(adapterRegistry.getAllAdapters().keys()).map(p => p.toUpperCase());

        let providersToRun = req.providers && req.providers.length > 0
            ? req.providers.map(p => p.trim().toUpperCase()) // NORMALIZE
            : allProviders;

        // PRIORITY: If profile has a specific provider assigned, ONLY search that provider
        if ((profile as any).provider) {
            const providerCode = (profile as any).provider.code || (profile as any).provider;
            providersToRun = [providerCode.toUpperCase()];
            console.log(`🎯 Provider-specific watcher: searching only ${providerCode}`);
        }
        // Otherwise, filter by profile's enabled providers if specified
        else if (profile.enabledProviders) {
            // Handle both string and array types (database stores as text)
            let enabledArray: string[];
            if (typeof profile.enabledProviders === 'string') {
                // Split comma-separated string or treat as single provider
                const providersStr = profile.enabledProviders as string;
                enabledArray = providersStr.includes(',')
                    ? providersStr.split(',').map(p => p.trim())
                    : [providersStr.trim()];
            } else if (Array.isArray(profile.enabledProviders)) {
                enabledArray = profile.enabledProviders;
            } else {
                enabledArray = [];
            }

            if (enabledArray.length > 0) {
                // Normalize to uppercase for comparison
                const normalizedEnabledProviders = enabledArray.map(ep => ep.trim().toUpperCase());
                providersToRun = providersToRun.filter(p =>
                    normalizedEnabledProviders.includes(p)
                );
            }
        }

        // 2.5 Resolve User for Trip Config
        const user = await this.userRepo.findOne({ where: { id: req.userId } });
        const userTripConfig = user ? {
            homeLatLng: user.homeLatitude && user.homeLongitude ? { lat: Number(user.homeLatitude), lng: Number(user.homeLongitude) } : undefined,
            engineType: (user.engineType as 'PETROL' | 'EV') || 'PETROL'
        } : undefined;

        // 3. Run for each provider
        for (const providerKey of providersToRun) {
            const preview = await this.runSingleProvider(providerKey, profile, requestId, req.options, userTripConfig);
            providerPreviews.push(preview);
        }

        // 4. Summarize
        const overallSummary = this.summarizeAll(providerPreviews);

        const response: PreviewResponse = {
            requestId,
            generatedAt,
            mode: req.mode,
            profile: {
                // Return sanitized profile structure
                ...profile
            },
            providers: providerPreviews,
            overallSummary,
            sideEffects: {
                observationsStored: false,
                alertsGenerated: false,
                emailsSent: false
            },
            warnings: []
        };

        return response;
    }

    private async runSingleProvider(
        providerKey: string,
        profile: Partial<HolidayProfile>,
        requestId: string,
        options: PreviewOptions = {},
        userTripConfig?: { homeLatLng?: { lat: number; lng: number }; engineType: 'PETROL' | 'EV' }
    ): Promise<ProviderPreview> {
        const startTotal = Date.now();
        const timing = { fetch: 0, parse: 0, match: 0, enrich: 0, total: 0 };
        // COMPLIANCE: Initialize with real values, not hardcoded
        const compliance = {
            scrapingEnabled: process.env.SCRAPING_ENABLED !== 'false',
            robotsAllowed: false,
            playwrightUsed: false,
            rateLimited: false
        };

        let status = 'OK';
        const results = { matched: [] as PreviewResult[], other: [] as PreviewResult[] };
        const summary = {
            totalCandidates: 0, matchStrong: 0, matchWeak: 0, matchUnknown: 0,
            mismatch: 0, lowestMatchedPriceGbp: null as number | null
        };

        // Check global kill switch
        if (process.env.SCRAPING_ENABLED === 'false') {
            status = 'DISABLED';
            compliance.scrapingEnabled = false;
            timing.total = Date.now() - startTotal;
            return { providerKey, status, timingMs: timing, compliance, results, summary };
        }

        // Get Adapter (registry uses lowercase keys)
        let adapter;
        try {
            adapter = adapterRegistry.getAdapter(providerKey.toLowerCase());
        } catch (e) {
            status = 'ERROR'; // Adapter not found
            return { providerKey, status, timingMs: timing, compliance, results, summary };
        }

        if (!adapter.isEnabled()) {
            console.log(`DEBUG: Adapter ${providerKey} is DISABLED via isEnabled() check`);
            status = 'DISABLED';
            return { providerKey, status, timingMs: timing, compliance, results, summary };
        }

        console.log(`DEBUG: Adapter ${providerKey} is ENABLED. Starting search...`);

        // Prepare Search Params from Profile
        const adapterParams = {
            provider: providerKey,
            dateWindow: {
                start: profile.dateStart instanceof Date ? profile.dateStart.toISOString().split('T')[0] : (profile.dateStart as unknown as string),
                end: profile.dateEnd instanceof Date ? profile.dateEnd.toISOString().split('T')[0] : (profile.dateEnd as unknown as string)
            },
            nights: { min: profile.durationNightsMin!, max: profile.durationNightsMax! },
            party: { adults: profile.partySizeAdults!, children: profile.partySizeChildren! },
            pets: profile.petsNumber || 0,
            parks: profile.parkIds,
            region: profile.region,
            accommodation: profile.accommodationType as any,
            minBedrooms: profile.minBedrooms!,
            peakTolerance: (profile.peakTolerance === PeakTolerance.OFFPEAK_ONLY ? 'offpeak' : (profile.peakTolerance === PeakTolerance.PEAK_OK ? 'peak' : 'mixed')) as 'offpeak' | 'mixed' | 'peak',
            metadata: profile.metadata as Record<string, unknown> // Pass metadata for provider-specific logic (e.g. Boats)
        };

        // COMPLIANCE: Check robots.txt
        // Note: buildSearchUrl is protected, so we'll default to true for now
        // Individual adapters can override this in their search() method
        compliance.robotsAllowed = true;

        // FETCH
        const t0 = Date.now();
        let rawResults: PriceResult[] = [];
        let usedPlaywright = false;
        try {
            console.log(`DEBUG: Calling adapter.search() for ${providerKey}`);
            rawResults = await adapter.search(adapterParams);
            console.log(`DEBUG: adapter.search() returned ${rawResults.length} results`);
            usedPlaywright = options.forcePlaywright || false;
        } catch (e: unknown) {
            console.error(`Preview fetch failed for ${providerKey}`, e);
            status = 'FETCH_FAILED';
            if ((e as Error).message?.includes('robots')) status = 'BLOCKED_ROBOTS';
        }
        compliance.playwrightUsed = usedPlaywright;
        const timingMs = { ...timing, fetch: Date.now() - t0 };

        // MATCH
        const t1 = Date.now();
        summary.totalCandidates = rawResults.length;

        for (const candidate of rawResults) {
            // Classify
            const classification = ResultMatcher.classify(candidate, {
                targetData: {
                    dateStart: adapterParams.dateWindow.start,
                    nights: candidate.stayNights,
                    party: adapterParams.party,
                    pets: adapterParams.pets,
                    accommodationType: adapterParams.accommodation,
                    minBedrooms: adapterParams.minBedrooms
                } as any // Cast because targetData expects strict types but adapterParams might have optional? No, wait. ResultMatcher context expects strict.
            });

            let confidence = classification.confidence;
            const reasons = { passed: [], failed: [], unknown: [], softNotes: [] } as any;

            // Manual Date Range Check (since Matcher enforces exact)
            const resDate = new Date(candidate.stayStartDate);
            const profStart = new Date(adapterParams.dateWindow.start);
            // Handle specific date (null end) by defaulting to start date
            const profEnd = adapterParams.dateWindow.end ? new Date(adapterParams.dateWindow.end) : new Date(profStart);

            const inDateRange = resDate >= profStart && resDate <= profEnd;
            if (!inDateRange) {
                console.log(`DEBUG: REJECTED ${candidate.propertyName}: Date ${candidate.stayStartDate} outside window ${adapterParams.dateWindow.start}-${adapterParams.dateWindow.end}`);
                confidence = MatchConfidence.MISMATCH;
                reasons.failed.push({ code: 'DATE_OUT_OF_RANGE', message: `Date ${candidate.stayStartDate} not in profile window` });
            } else if (profile.budgetCeilingGbp && candidate.priceTotalGbp > profile.budgetCeilingGbp) {
                console.log(`DEBUG: REJECTED ${candidate.propertyName}: Price £${candidate.priceTotalGbp} exceeds budget £${profile.budgetCeilingGbp}`);
                confidence = MatchConfidence.MISMATCH;
                reasons.failed.push({ code: 'OVER_BUDGET', message: `Price £${candidate.priceTotalGbp} exceeds budget £${profile.budgetCeilingGbp}` });
            } else {
                const context = {
                    targetData: {
                        dateStart: candidate.stayStartDate, // align
                        nights: candidate.stayNights,       // align
                        party: adapterParams.party,
                        pets: adapterParams.pets,
                        accommodationType: adapterParams.accommodation,
                        minBedrooms: adapterParams.minBedrooms
                    }
                };

                const strictMatch = ResultMatcher.classify(candidate, context);
                confidence = strictMatch.confidence;

                if (confidence !== MatchConfidence.STRONG && confidence !== MatchConfidence.WEAK) {
                    console.log(`DEBUG: REJECTED ${candidate.propertyName || 'unnamed'} (£${candidate.priceTotalGbp}): Confidence ${confidence}. Desc: ${strictMatch.description}`);
                    if (confidence === MatchConfidence.MISMATCH) {
                        reasons.failed.push({ code: 'MISMATCH', message: strictMatch.description });
                    } else if (confidence === MatchConfidence.UNKNOWN) {
                        // ...
                    }
                } else {
                    console.log(`DEBUG: ACCEPTED ${candidate.propertyName || 'unnamed'} (£${candidate.priceTotalGbp}): Confidence ${confidence}`);
                }
            }

            // SeriesKey Generation Safety - Use REAL parkId from candidate
            // PriceResult has parkId confirmed by type definition
            const realParkId = candidate.parkId || (candidate as any).park_id || (candidate as any).locationId;
            const requiredFields = [candidate.stayStartDate, candidate.stayNights, candidate.accomType, realParkId];
            const hasRequiredFields = requiredFields.every(f => f !== undefined && f !== null);

            let seriesKey: string | null = null;
            if (hasRequiredFields) {
                try {
                    seriesKey = generateSeriesKey({
                        providerId: providerKey,
                        stayStartDate: candidate.stayStartDate,
                        stayNights: candidate.stayNights,
                        parkId: realParkId,
                        accomTypeId: candidate.accomType
                    });
                } catch (err) {
                    reasons.failed.push({ code: 'SERIESKEY_GENERATION_FAILED', message: 'Failed to generate key' });
                    seriesKey = null;
                }
            } else {
                reasons.failed.push({ code: 'SERIESKEY_INCOMPLETE', message: 'Missing critical fields (parkId, date, nights, or accomType)' });
                if (confidence !== MatchConfidence.MISMATCH) {
                    confidence = MatchConfidence.UNKNOWN;
                }
            }

            // Create PreviewResult
            const previewResult: PreviewResult = {
                confidence,
                providerKey,
                sourceUrl: candidate.sourceUrl || '',
                parkId: realParkId || 'UNKNOWN',
                stayStartDate: candidate.stayStartDate,
                stayNights: candidate.stayNights,
                accommodationType: candidate.accomType || 'UNKNOWN',
                bedrooms: candidate.bedrooms,
                tier: undefined,
                petsAllowed: candidate.petsAllowed,
                facilities: [],
                propertyName: candidate.propertyName,
                location: candidate.location,
                availability: candidate.availability,
                price: {
                    totalGbp: candidate.priceTotalGbp,
                    perNightGbp: candidate.pricePerNightGbp
                },
                seriesKey: seriesKey || 'null',
                reasons,
                matchDetails: candidate.matchDetails || (confidence === MatchConfidence.MISMATCH
                    ? (reasons.failed[0]?.message || 'Mismatch')
                    : (reasons.passed[0]?.message || 'Match'))
            };

            // 3.5 Enrichment with Trip Cost
            if (userTripConfig?.homeLatLng && previewResult.confidence !== MatchConfidence.MISMATCH) {
                try {
                    // Resolve destination lat/lng from Database if possible
                    // For now, use whatever the candidate has or a mock
                    const destination = candidate.latitude && candidate.longitude
                        ? { lat: Number(candidate.latitude), lng: Number(candidate.longitude) }
                        : { lat: 53.0, lng: -2.0 }; // Fallback

                    previewResult.tripCost = await this.tripCostService.calculateTotalTripCost({
                        originLatLng: userTripConfig.homeLatLng,
                        destinationLatLng: destination,
                        stayNights: previewResult.stayNights,
                        providerKey: providerKey.toLowerCase(),
                        engineType: userTripConfig.engineType,
                        partySize: {
                            adults: profile.partySizeAdults || 2,
                            children: profile.partySizeChildren || 0
                        }
                    });
                } catch (err) {
                    console.error(`TripCost enrichment failed for ${candidate.propertyName}`, err);
                }
            }

            // Summary Stats
            if (confidence === MatchConfidence.STRONG) summary.matchStrong++;
            else if (confidence === MatchConfidence.WEAK) summary.matchWeak++;
            else if (confidence === MatchConfidence.UNKNOWN) summary.matchUnknown++;
            else summary.mismatch++;

            // Bucket
            if (confidence === MatchConfidence.STRONG || (options.allowWeakMatches && confidence === MatchConfidence.WEAK)) {
                results.matched.push(previewResult);
                console.log(`DEBUG: Added to matched: ${candidate.propertyName || 'unnamed'} (£${candidate.priceTotalGbp}) - confidence: ${confidence}`);
                if (!summary.lowestMatchedPriceGbp || candidate.priceTotalGbp < summary.lowestMatchedPriceGbp) {
                    summary.lowestMatchedPriceGbp = candidate.priceTotalGbp;
                }
            } else {
                console.log(`DEBUG: NOT added to matched: ${candidate.propertyName || 'unnamed'} (£${candidate.priceTotalGbp}) - confidence: ${confidence}, allowWeakMatches: ${options.allowWeakMatches}`);
                if (options.includeMismatches || options.includeDebug) {
                    results.other.push(previewResult);
                }
            }
        }
        timingMs.match = Date.now() - t1;
        timingMs.total = Date.now() - startTotal;

        // SORTING & LIMITING
        const sortOrder = profile.sortOrder || 'PRICE_ASC';
        results.matched.sort((a, b) => {
            if (sortOrder === 'PRICE_ASC') return a.price.totalGbp - b.price.totalGbp;
            if (sortOrder === 'PRICE_DESC') return b.price.totalGbp - a.price.totalGbp;
            if (sortOrder === 'DATE_ASC') return new Date(a.stayStartDate).getTime() - new Date(b.stayStartDate).getTime();
            return 0;
        });

        // Apply Max Results
        const effectiveMax = options.maxResults || profile.maxResults || 20;
        if (results.matched.length > effectiveMax) {
            results.matched = results.matched.slice(0, effectiveMax);
        }

        // Audit Log - Always log for preview
        await this.logRun(providerKey, profile, status, rawResults.length, summary, requestId);

        return {
            providerKey,
            status,
            timingMs,
            compliance,
            results,
            summary
        };
    }

    private async logRun(
        providerKey: string,
        profile: Partial<HolidayProfile>,
        status: string,
        count: number,
        summary: any, // Use any to allow property access on generic Record
        requestId: string
    ) {
        // Find Provider Entity
        const provider = await this.providerRepo.findOne({ where: { code: providerKey } });
        if (!provider) return;

        // Map status string to ProviderStatus enum
        let providerStatus: ProviderStatus = ProviderStatus.OK;
        if (status === 'FETCH_FAILED') providerStatus = ProviderStatus.FETCH_FAILED;
        else if (status === 'PARSE_FAILED') providerStatus = ProviderStatus.PARSE_FAILED;
        else if (status === 'BLOCKED_ROBOTS' || status === 'BLOCKED') providerStatus = ProviderStatus.BLOCKED;
        else if (status === 'TIMEOUT') providerStatus = ProviderStatus.TIMEOUT;
        else if (status !== 'OK') providerStatus = ProviderStatus.FETCH_FAILED;

        // Generate request fingerprint (hash of profile params)
        const crypto = await import('crypto');
        const fingerprintData = JSON.stringify({
            provider: providerKey,
            dateStart: profile.dateStart,
            dateEnd: profile.dateEnd,
            nights: { min: profile.durationNightsMin, max: profile.durationNightsMax },
            party: { adults: profile.partySizeAdults, children: profile.partySizeChildren }
        });
        const requestFingerprint = crypto.createHash('sha256').update(fingerprintData).digest('hex').substring(0, 16);

        const run = this.fetchRunRepo.create({
            provider,
            runType: RunType.MANUAL_PREVIEW,
            scheduledFor: new Date(),
            startedAt: new Date(),
            finishedAt: new Date(),
            status: status === 'OK' ? RunStatus.OK : RunStatus.ERROR,
            requestId,
            providerStatus,
            requestFingerprint,
            responseSnapshotRef: JSON.stringify({
                summary,
                parseStats: {
                    total: count,
                    matched: summary.matchStrong + summary.matchWeak
                }
            })
        });

        await this.fetchRunRepo.save(run);
    }

    private summarizeAll(previews: ProviderPreview[]) {
        return {
            providersRequested: previews.length,
            providersSucceeded: previews.filter(p => p.status === 'OK').length,
            providersFailed: previews.filter(p => p.status !== 'OK').length,
            totalMatched: previews.reduce((sum, p) => sum + p.results.matched.length, 0),
            lowestMatchedPriceGbp: previews.reduce((min, p) => {
                if (p.summary.lowestMatchedPriceGbp === null) return min;
                if (min === null) return p.summary.lowestMatchedPriceGbp;
                return Math.min(min, p.summary.lowestMatchedPriceGbp);
            }, null as number | null)
        };
    }
}

export const previewService = new PreviewService();

import { TripCost, TripCostRequest, OnParkSpendingConfig } from '../types/trip-cost.types';
import * as fs from 'fs';
import * as path from 'path';

/**
 * TripCostService
 * Responsible for calculating total staycation costs including fuel and on-park spending.
 * Optimized for 2026 Strategy: EV-awareness, Island Tax (Ferry), and robust fallback routing.
 */
export class TripCostService {
  private static instance: TripCostService;
  private onParkSpendingData: Record<string, any> = {};

  // Fuel Config (Pence Per Mile) - Defaults from Strategy 2026
  private readonly FUEL_PPM_PETROL = Number(process.env.FUEL_PPM_PETROL) || 18;
  private readonly FUEL_PPM_EV = Number(process.env.FUEL_PPM_EV) || 8;
  private readonly EV_CHARGING_BUFFER = 1.05; // 5% time buffer for charging stops

  // Ferry Lookup (Simple postcode/region based lookup for "Island Tax")
  private readonly FERRY_ROUTES: Record<string, number> = {
    'PO30': 85, // Isle of Wight (Cowes/Fishbourne)
    'PO31': 85,
    'PO33': 85,
    'PA75': 120, // Mull
    'IV51': 150, // Skye
    'TR21': 200, // Scilly Isles
    'PH41': 130, // Mallaig (Ferry to Skye/Isles)
  };

  private constructor() {
    this.loadSpendingData();
  }

  private loadSpendingData() {
    try {
      const configPath = path.join(__dirname, '../config/on-park-spending.json');
      if (fs.existsSync(configPath)) {
        this.onParkSpendingData = JSON.parse(fs.readFileSync(configPath, 'utf-8'));
      }
    } catch (error) {
      // In production, we'd log this to a proper monitoring system
      console.error('[TripCostService] Failed to load on-park spending data:', error);
    }
  }

  public static getInstance(): TripCostService {
    if (!TripCostService.instance) {
      TripCostService.instance = new TripCostService();
    }
    return TripCostService.instance;
  }

  /**
   * Calculates the estimated total trip cost based on origin, destination and provider.
   */
  public async calculateTotalTripCost(request: TripCostRequest): Promise<TripCost> {
    const { distanceMiles, drivingMinutes, isEstimate } = await this.calculateTravelDistance(
      request.originLatLng,
      request.destinationLatLng
    );

    // Fuel Calculation (Pence to Pounds)
    const ppm = request.engineType === 'EV' ? this.FUEL_PPM_EV : this.FUEL_PPM_PETROL;
    const fuelCostGbp = (distanceMiles * ppm) / 100;

    // Time Buffer for EV (Charging stops)
    const finalMinutes = request.engineType === 'EV' ? drivingMinutes * this.EV_CHARGING_BUFFER : drivingMinutes;

    // Ferry Calculation (Island Tax)
    const ferryCostGbp = this.getFerryEstimate(request.destinationLatLng);

    // On-Park Spending (Aggregated low/high estimates)
    const { low: onParkLow, high: onParkHigh } = this.getOnParkSpendingEstimate(
      request.providerKey,
      request.stayNights
    );

    // Accommodation Price (Placeholder - actual implementation would fetch from SearchResult)
    const accommodationPriceGbp = request.stayNights * 125; // Average £125/night

    return {
      distanceMiles: Math.round(distanceMiles),
      drivingMinutes: Math.round(finalMinutes),
      fuelCostGbp: Number(fuelCostGbp.toFixed(2)),
      ferryCostGbp,
      engineType: request.engineType,
      onParkEstLow: Math.round(onParkLow),
      onParkEstHigh: Math.round(onParkHigh),
      accommodationPriceGbp,
      totalLow: Number((accommodationPriceGbp + fuelCostGbp + ferryCostGbp + onParkLow).toFixed(2)),
      totalHigh: Number((accommodationPriceGbp + fuelCostGbp + ferryCostGbp + onParkHigh).toFixed(2)),
      calculatedAt: new Date().toISOString(),
      currency: 'GBP',
      isEstimate
    };
  }

  /**
   * Calculates travel distance and time with robust multi-provider fallback.
   * Priority: OSRM (Self-hosted/Free) -> Mapbox (Fallback) -> Haversine (Emergency)
   */
  private async calculateTravelDistance(origin: any, destination: any): Promise<{ distanceMiles: number; drivingMinutes: number; isEstimate: boolean }> {
    // 1. OSRM Logic
    try {
      if (process.env.OSRM_URL) {
        // Implementation for OSRM URL fetch would go here
        // const response = await fetch(`${process.env.OSRM_URL}/route/v1/driving/...`)
      }
      // Simulating failure to trigger the fallback logic as per requirements
      throw new Error('OSRM_NOT_CONFIGURED');
    } catch (err) {
      // 2. Mapbox Logic
      try {
        if (process.env.MAPBOX_ACCESS_TOKEN) {
          // Implementation for Mapbox Directions API would go here
        }
        throw new Error('MAPBOX_NOT_CONFIGURED');
      } catch (mapboxErr) {
        // 3. Final Fallback: Haversine distance ("As the crow flies") + 25% road-winding factor
        const crowdMiles = this.calculateHaversineDistance(
          origin.lat, origin.lng,
          destination.lat, destination.lng
        );

        const roadMiles = crowdMiles * 1.25; // 25% added for UK road winding
        const roadMinutes = (roadMiles / 45) * 60; // Assume 45mph average speed for mixed UK roads

        return {
          distanceMiles: roadMiles,
          drivingMinutes: roadMinutes,
          isEstimate: true
        };
      }
    }
  }

  /**
   * Haversine formula to find the distance between two points in miles.
   */
  private calculateHaversineDistance(lat1: number, lon1: number, lat2: number, lon2: number): number {
    const R = 3958.8; // Radius of the Earth in miles
    const dLat = (lat2 - lat1) * (Math.PI / 180);
    const dLon = (lon2 - lon1) * (Math.PI / 180);
    const a = 
      Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(lat1 * (Math.PI / 180)) * Math.cos(lat2 * (Math.PI / 180)) * 
      Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
  }

  /**
   * Identifies if a destination is on an island and returns the estimated ferry cost.
   */
  private getFerryEstimate(destination: any): number {
    // In production, we'd use a reverse-geocoding service to get the postcode or a GeoJSON polygon check.
    // For this implementation, we check rough bounding boxes of known UK island destinations.

    // Isle of Wight bounding box
    if (destination.lat < 50.8 && destination.lat > 50.5 && destination.lng < -1.0 && destination.lng > -1.6) {
      return this.FERRY_ROUTES['PO30'];
    }

    // Skye area
    if (destination.lat < 57.7 && destination.lat > 57.0 && destination.lng < -5.7 && destination.lng > -6.8) {
      return this.FERRY_ROUTES['IV51'];
    }

    return 0;
  }

  /**
   * Aggregates on-park spending estimates based on provider configuration.
   */
  private getOnParkSpendingEstimate(providerKey: string, stayNights: number): { low: number; high: number } {
    const config = this.onParkSpendingData[providerKey] || { dailyBaseSpend: 25, activityMultiplier: 1.2 };

    const baseTotal = config.dailyBaseSpend * stayNights;
    return {
      low: baseTotal,
      high: baseTotal * config.activityMultiplier
    };
  }
}
